/**
 * Cloud inference providers: one declaration per provider feeds configuration, credential scoping, disclosure policy
 * and request construction. The local appliance is not a provider here: a configuration without a provider id keeps
 * the original endpoint path (LOCAL_LLM_*, stored gateway token, X-Task-Class, endpoint failover) unchanged.
 *
 * Separate concepts:
 * - Provider definition (PROVIDERS): identity, wire protocol, default base URL, credential variable, auth style.
 * - Connection (ResolvedConnection): the base URL actually used, its credential scope and disclosure class.
 * - Model: the provider's model id, passed verbatim (ids may contain "/" and ":").
 * - Role binding: main, planner and coder each name their own provider; subagents and auxiliary calls inherit main.
 */
import fs from "node:fs";
import { classifyDestination } from "./core/egress.js";
import { parseProvidersDocument } from "./provider_file.js";

export type WireProtocol = "openai-chat" | "openai-responses" | "anthropic-messages";
export type AuthStyle = "bearer" | "x-api-key" | "header" | "none" | "oauth";

/** How an operator can connect a provider from the TUI or `nexus connect`. */
export interface ConnectMethod {
  id: string;
  label: string;
  kind: "key" | "browser" | "device";
  /** Uses another vendor's client identity; the providers' terms may not permit it. */
  unofficial?: boolean;
}

/** A model-id pattern (case-insensitive regular expression source) served over another wire protocol. */
export interface ProtocolRule {
  modelPattern: string;
  protocol: WireProtocol;
}

export interface ProviderDefinition {
  id: string;
  label: string;
  protocol: WireProtocol;
  /** Includes the provider's API path and version; nothing is appended except the operation path. */
  baseUrl?: string;
  /** Environment variable holding this provider's key (none for sign-in-only providers). Sent only to the connection's own origin. */
  credentialEnv?: string;
  methods: ConnectMethod[];
  /** The backend accepts streamed requests only; non-streaming calls are streamed internally. */
  streamOnly?: boolean;
  /** Request parameters this backend rejects for every model; never sent. */
  omitParams?: string[];
  auth: AuthStyle;
  /** Header carrying the key when `auth` is "header" (for example Azure OpenAI's `api-key`). */
  authHeader?: string;
  /** Models this provider serves over a different wire protocol than `protocol`; first matching pattern wins. */
  protocolRules?: ProtocolRule[];
  /** Headers this provider requires on every request. */
  staticHeaders?: Record<string, string>;
  /** Query parameters added to every request URL (for example Azure OpenAI's `api-version`). */
  query?: Record<string, string>;
  /** Ask the provider to report usage (and, where offered, cost) on streamed responses. */
  usage: "openrouter" | "stream-options" | "native";
}

export const PROVIDERS: Readonly<Record<string, ProviderDefinition>> = Object.freeze({
  openrouter: {
    id: "openrouter",
    label: "OpenRouter",
    protocol: "openai-chat",
    baseUrl: "https://openrouter.ai/api/v1",
    credentialEnv: "OPENROUTER_API_KEY",
    auth: "bearer",
    staticHeaders: { "X-Title": "Nexus" },
    usage: "openrouter",
    methods: [
      { id: "api-key", label: "API key", kind: "key" },
      { id: "openrouter-oauth", label: "Sign in with OpenRouter", kind: "browser" },
    ],
  },
  openai: {
    id: "openai",
    label: "OpenAI",
    protocol: "openai-responses",
    baseUrl: "https://api.openai.com/v1",
    credentialEnv: "OPENAI_API_KEY",
    auth: "bearer",
    usage: "native",
    methods: [{ id: "api-key", label: "API key", kind: "key" }],
  },
  anthropic: {
    id: "anthropic",
    label: "Anthropic",
    protocol: "anthropic-messages",
    baseUrl: "https://api.anthropic.com/v1",
    credentialEnv: "ANTHROPIC_API_KEY",
    auth: "x-api-key",
    staticHeaders: { "anthropic-version": "2023-06-01" },
    usage: "native",
    methods: [{ id: "api-key", label: "API key", kind: "key" }],
  },
  /** ChatGPT Plus/Pro plan through the Codex backend (unofficial: Codex CLI sign-in). */
  chatgpt: {
    id: "chatgpt",
    label: "ChatGPT plan",
    protocol: "openai-responses",
    baseUrl: "https://chatgpt.com/backend-api/codex",
    auth: "oauth",
    staticHeaders: { originator: "nexus" },
    usage: "native",
    streamOnly: true,
    // The Codex backend serves reasoning models only and sets its own output limit.
    omitParams: ["temperature", "max_output_tokens"],
    methods: [{ id: "chatgpt-oauth", label: "Sign in with ChatGPT (unofficial)", kind: "browser", unofficial: true }],
  },
  /** GitHub Copilot subscription (unofficial: VS Code Copilot sign-in). */
  copilot: {
    id: "copilot",
    label: "GitHub Copilot",
    protocol: "openai-chat",
    baseUrl: "https://api.githubcopilot.com",
    auth: "oauth",
    usage: "native",
    // Copilot serves some models through the Responses API only.
    protocolRules: [{ modelPattern: "^gpt-5", protocol: "openai-responses" }],
    methods: [{ id: "copilot-device", label: "Sign in with GitHub (unofficial)", kind: "device", unofficial: true }],
  },
  /** Any other OpenAI-compatible Chat Completions service; its base URL must be configured by the operator. */
  compatible: {
    id: "compatible",
    label: "OpenAI-compatible",
    protocol: "openai-chat",
    credentialEnv: "NEXUS_COMPATIBLE_API_KEY",
    auth: "bearer",
    usage: "stream-options",
    methods: [{ id: "api-key", label: "API key", kind: "key" }],
  },
});

/** Providers the operator declared in ~/.config/nexus/providers.json; built-in ids can never be replaced. */
let operatorProviders: Readonly<Record<string, ProviderDefinition>> = Object.freeze({});

/**
 * Providers shipped as data (src/providers.catalog.json, the same schema as the operator's file): the OpenAI-compatible
 * long tail. Operator definitions of the same id take precedence; built-ins are never replaced. Read on first use.
 */
let catalogProviders: readonly ProviderDefinition[] | undefined;
function catalog(): readonly ProviderDefinition[] {
  if (!catalogProviders) {
    const raw = JSON.parse(fs.readFileSync(new URL("./providers.catalog.json", import.meta.url), "utf8"));
    catalogProviders = parseProvidersDocument(raw).filter((d) => !Object.prototype.hasOwnProperty.call(PROVIDERS, d.id));
  }
  return catalogProviders;
}

export function setOperatorProviders(defs: readonly ProviderDefinition[]): void {
  const next: Record<string, ProviderDefinition> = {};
  for (const def of defs) {
    if (Object.prototype.hasOwnProperty.call(PROVIDERS, def.id)) throw new Error(`providers.${def.id}: a built-in provider id cannot be redefined`);
    next[def.id] = def;
  }
  operatorProviders = Object.freeze(next);
}

/** Where a provider definition comes from. */
export function providerSource(id: string): "built-in" | "catalog" | "providers.json" | undefined {
  if (Object.prototype.hasOwnProperty.call(PROVIDERS, id)) return "built-in";
  if (Object.prototype.hasOwnProperty.call(operatorProviders, id)) return "providers.json";
  return catalog().some((d) => d.id === id) ? "catalog" : undefined;
}

/** Every known provider: the built-ins, then the operator's own, in declaration order. The one place callers enumerate providers. */
export function allProviders(): ProviderDefinition[] {
  return [...Object.values(PROVIDERS), ...catalog().filter((d) => !Object.prototype.hasOwnProperty.call(operatorProviders, d.id)), ...Object.values(operatorProviders)];
}

export function providerIds(): string[] {
  return allProviders().map((d) => d.id);
}

export function providerDefinition(id: string | undefined): ProviderDefinition | undefined {
  if (!id) return undefined;
  if (Object.prototype.hasOwnProperty.call(PROVIDERS, id)) return PROVIDERS[id];
  if (Object.prototype.hasOwnProperty.call(operatorProviders, id)) return operatorProviders[id];
  return catalog().find((d) => d.id === id);
}

/** `NEXUS_<ID>_BASE_URL`: the operator's override of a provider's base URL. */
export function baseUrlSetting(id: string): string {
  return `NEXUS_${id.toUpperCase().replace(/-/g, "_")}_BASE_URL`;
}

export function originOf(url: string | undefined): string | undefined {
  if (!url?.trim()) return undefined;
  try {
    return new URL(url.trim()).origin;
  } catch {
    return undefined;
  }
}

export interface ResolvedConnection {
  /** Undefined for the legacy appliance/endpoint path. */
  providerId?: string;
  label: string;
  protocol: WireProtocol;
  auth: AuthStyle;
  authHeader?: string;
  staticHeaders: Record<string, string>;
  query: Record<string, string>;
  usage: ProviderDefinition["usage"] | "none";
  /** Whether requests carry the appliance's X-Task-Class routing hint. */
  sendTaskClass: boolean;
  streamOnly: boolean;
  omitParams: string[];
}

/** The wire protocol a provider's rules assign to this model, when one applies. */
export function protocolFor(providerId: string | undefined, model: string): WireProtocol | undefined {
  return providerDefinition(providerId)?.protocolRules?.find((r) => new RegExp(r.modelPattern, "i").test(model))?.protocol;
}

export function connectionFor(providerId: string | undefined, model = ""): ResolvedConnection {
  const def = providerDefinition(providerId);
  if (!def) {
    // Usage is requested (OpenAI-compatible servers such as llama.cpp, vLLM and the appliance gateway report it, with
    // cached-token counts); a server that rejects stream_options has it dropped and the request retried.
    return { label: "endpoint", protocol: "openai-chat", auth: "bearer", staticHeaders: {}, query: {}, usage: "stream-options", sendTaskClass: true, streamOnly: false, omitParams: [] };
  }
  return {
    providerId: def.id,
    label: def.label,
    protocol: protocolFor(def.id, model) ?? def.protocol,
    auth: def.auth,
    ...(def.authHeader ? { authHeader: def.authHeader } : {}),
    staticHeaders: { ...(def.staticHeaders ?? {}) },
    query: { ...(def.query ?? {}) },
    usage: def.usage,
    sendTaskClass: false,
    streamOnly: Boolean(def.streamOnly),
    omitParams: [...(def.omitParams ?? [])],
  };
}

/**
 * Disclosure class of a destination: "cloud" when content sent there leaves the operator's machines and network.
 * URL locality is not sufficient: an origin the operator lists in NEXUS_CLOUD_ROUTED_ORIGINS (a local gateway that
 * forwards to a cloud service) is cloud, and every named provider except `compatible` is cloud by definition.
 */
export function disclosureClass(url: string, providerId: string | undefined, cloudRoutedOrigins: readonly string[] = []): "local" | "cloud" {
  if (providerId && providerId !== "compatible") return "cloud";
  const origin = originOf(url);
  if (origin && cloudRoutedOrigins.includes(origin)) return "cloud";
  const boundary = classifyDestination(url);
  return boundary === "EXTERNAL_PUBLIC" || boundary === "EXTERNAL_BOUNDED" ? "cloud" : "local";
}

export function parseOriginList(raw: string | undefined): string[] {
  return (raw ?? "").split(",").map((o) => originOf(o)).filter((o): o is string => Boolean(o));
}

/** The environment variable a provider connection reads its key from (for operator-facing messages). */
export function operatorSettingKeyForAuth(id: string): string {
  const def = providerDefinition(id);
  return def?.credentialEnv ?? (def ? `sign in with /model → ctrl+p → ${def.label}` : "the provider's API key variable");
}
import { CURRENT_STATE_SCHEMA_VERSION } from "./core/state_schema.js";
/**
 * Machine-Readable Release Compatibility Metadata (REQ-REL-116, ACC-UPG-07)
 *
 * Defines versioned metadata schema for published releases, component compatibility,
 * and state/config schema boundaries.
 */

export const COMPATIBILITY_METADATA_FILENAME = "compatibility.json";
export const COMPATIBILITY_SCHEMA_VERSION = 1;
export const CURRENT_CONFIG_SCHEMA_VERSION = 1;

export interface ComponentVersions {
  cli: string;
  core: string;
  tui: string;
  harness: string;
}

export interface SchemaCompatibility {
  configSchemaVersion: number;
  stateSchemaVersion: number;
  minSupportedConfigVersion: number;
  minSupportedStateVersion: number;
}

export interface PlatformAsset {
  archive: string;
  sha256?: string;
  libc?: string;
  os: string;
  arch: string;
}

export interface ReleaseCompatibilityMetadata {
  schemaVersion: number;
  product: "nexus-code";
  version: string;
  revision: string;
  builtAt: string;
  minimumUpdaterVersion?: string;
  components: ComponentVersions;
  compatibility: SchemaCompatibility;
  platforms: Record<string, PlatformAsset>;
}

export interface CompatibilityCheckResult {
  compatible: boolean;
  isLegacy: boolean;
  reasons: string[];
  metadata?: ReleaseCompatibilityMetadata;
}

/**
 * Generates release compatibility metadata for packaging.
 */
export function generateCompatibilityMetadata(
  version: string,
  revision: string,
  platforms?: Record<string, PlatformAsset>
): ReleaseCompatibilityMetadata {
  const normVersion = version.replace(/^v/, "");
  return {
    schemaVersion: COMPATIBILITY_SCHEMA_VERSION,
    product: "nexus-code",
    version: normVersion,
    revision,
    builtAt: new Date().toISOString(),
    minimumUpdaterVersion: "0.1.0-alpha.2",
    components: {
      cli: normVersion,
      core: normVersion,
      tui: normVersion,
      harness: normVersion,
    },
    compatibility: {
      configSchemaVersion: 1,
      stateSchemaVersion: CURRENT_STATE_SCHEMA_VERSION,
      minSupportedConfigVersion: 1,
      minSupportedStateVersion: 0,
    },
    platforms: platforms ?? {
      "linux-x86_64": {
        archive: `nexus-linux-x86_64-v${normVersion}.tar.gz`,
        os: "linux",
        arch: "x86_64",
        libc: "glibc-2.35",
      },
    },
  };
}

/**
 * Validates the structure and consistency of compatibility metadata.
 */
export function validateCompatibilityMetadata(data: any): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  if (!data || typeof data !== "object") {
    return { valid: false, errors: ["Metadata is not an object"] };
  }
  if (data.product !== "nexus-code") {
    errors.push(`Invalid product '${data.product}', expected 'nexus-code'`);
  }
  if (typeof data.version !== "string" || !parseSemver(data.version)) {
    errors.push("Missing or invalid SemVer 'version'");
  }
  if (data.schemaVersion !== COMPATIBILITY_SCHEMA_VERSION) {
    errors.push(`Unsupported 'schemaVersion' ${data.schemaVersion}; expected ${COMPATIBILITY_SCHEMA_VERSION}`);
  }
  if (typeof data.revision !== "string" || !data.revision.trim()) errors.push("Missing or invalid 'revision'");
  if (typeof data.builtAt !== "string" || Number.isNaN(Date.parse(data.builtAt))) errors.push("Missing or invalid 'builtAt'");
  if (data.minimumUpdaterVersion !== undefined && (typeof data.minimumUpdaterVersion !== "string" || !parseSemver(data.minimumUpdaterVersion))) {
    errors.push("Invalid SemVer 'minimumUpdaterVersion'");
  }
  if (!data.compatibility || typeof data.compatibility !== "object") {
    errors.push("Missing 'compatibility' section");
  } else {
    const c = data.compatibility;
    const schemaFields = ["stateSchemaVersion", "configSchemaVersion", "minSupportedStateVersion", "minSupportedConfigVersion"] as const;
    for (const field of schemaFields) {
      if (!Number.isSafeInteger(c[field]) || c[field] < 0) errors.push(`Missing or invalid 'compatibility.${field}'`);
    }
    if (Number.isSafeInteger(c.stateSchemaVersion) && Number.isSafeInteger(c.minSupportedStateVersion) && c.minSupportedStateVersion > c.stateSchemaVersion) {
      errors.push("compatibility.minSupportedStateVersion exceeds stateSchemaVersion");
    }
    if (Number.isSafeInteger(c.configSchemaVersion) && Number.isSafeInteger(c.minSupportedConfigVersion) && c.minSupportedConfigVersion > c.configSchemaVersion) {
      errors.push("compatibility.minSupportedConfigVersion exceeds configSchemaVersion");
    }
  }
  if (!data.components || typeof data.components !== "object") {
    errors.push("Missing 'components' section");
  } else {
    for (const name of ["cli", "core", "tui", "harness"] as const) {
      if (typeof data.components[name] !== "string" || !parseSemver(data.components[name])) errors.push(`Missing or invalid SemVer 'components.${name}'`);
      else if (data.components[name] !== data.version) errors.push(`Component '${name}' version must match release version '${data.version}'`);
    }
  }
  if (!data.platforms || typeof data.platforms !== "object" || Object.keys(data.platforms).length === 0) {
    errors.push("Missing or empty 'platforms' section");
  } else {
    for (const [key, asset] of Object.entries(data.platforms) as Array<[string, any]>) {
      if (!asset || typeof asset !== "object") {
        errors.push(`Invalid platform asset '${key}'`);
        continue;
      }
      for (const field of ["archive", "os", "arch"] as const) {
        if (typeof asset[field] !== "string" || !asset[field].trim()) errors.push(`Missing or invalid 'platforms.${key}.${field}'`);
      }
      if (asset.sha256 !== undefined && (typeof asset.sha256 !== "string" || !/^[a-f0-9]{64}$/i.test(asset.sha256))) {
        errors.push(`Invalid SHA-256 digest 'platforms.${key}.sha256'`);
      }
      if (asset.libc !== undefined && typeof asset.libc !== "string") errors.push(`Invalid 'platforms.${key}.libc'`);
    }
  }
  return { valid: errors.length === 0, errors };
}

function parseSemver(input: string): { major: number; minor: number; patch: number; prerelease: Array<string | number> } | null {
  const clean = input.trim().replace(/^[vV]/, "");
  const match = clean.match(/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/);
  if (!match) return null;
  const major = Number(match[1]);
  const minor = Number(match[2]);
  const patch = Number(match[3]);
  if (![major, minor, patch].every(Number.isSafeInteger)) return null;
  const prerelease = match[4] ? match[4].split(".").map((part) => /^\d+$/.test(part) ? Number(part) : part) : [];
  if (prerelease.some((part, index) => typeof part === "number" && (part > Number.MAX_SAFE_INTEGER || /^0\d/.test(match[4]!.split(".")[index])))) return null;
  return { major, minor, patch, prerelease };
}

function compareSemver(left: NonNullable<ReturnType<typeof parseSemver>>, right: NonNullable<ReturnType<typeof parseSemver>>): number {
  for (const key of ["major", "minor", "patch"] as const) {
    if (left[key] !== right[key]) return left[key] > right[key] ? 1 : -1;
  }
  if (!left.prerelease.length || !right.prerelease.length) {
    return left.prerelease.length === right.prerelease.length ? 0 : left.prerelease.length ? -1 : 1;
  }
  const count = Math.min(left.prerelease.length, right.prerelease.length);
  for (let i = 0; i < count; i++) {
    const a = left.prerelease[i];
    const b = right.prerelease[i];
    if (a === b) continue;
    if (typeof a === "number" && typeof b !== "number") return -1;
    if (typeof a !== "number" && typeof b === "number") return 1;
    return a < b ? -1 : 1;
  }
  return left.prerelease.length === right.prerelease.length ? 0 : left.prerelease.length < right.prerelease.length ? -1 : 1;
}

function canonicalJson(value: any): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

/** Ensures the detached metadata asset is the checksummed, archive-bound form of package metadata. */
export function validateCompatibilityAssetBinding(
  external: ReleaseCompatibilityMetadata,
  embedded: ReleaseCompatibilityMetadata,
  expectedVersion: string,
  expectedArchive: string,
  actualArchiveSha256: string,
  platformKey = "linux-x86_64"
): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  const externalValidation = validateCompatibilityMetadata(external);
  const embeddedValidation = validateCompatibilityMetadata(embedded);
  if (!externalValidation.valid) errors.push(...externalValidation.errors.map((error) => `external ${error}`));
  if (!embeddedValidation.valid) errors.push(...embeddedValidation.errors.map((error) => `embedded ${error}`));
  const externalAsset = external?.platforms?.[platformKey];
  const embeddedAsset = embedded?.platforms?.[platformKey];
  if (!externalAsset || externalAsset.archive !== expectedArchive) errors.push(`external metadata does not name expected archive '${expectedArchive}'`);
  if (!embeddedAsset || embeddedAsset.archive !== expectedArchive) errors.push(`embedded metadata does not name expected archive '${expectedArchive}'`);
  if (externalAsset?.sha256?.toLowerCase() !== actualArchiveSha256.toLowerCase()) errors.push("external metadata archive digest does not match downloaded archive");
  if (external?.version !== expectedVersion.replace(/^[vV]/, "") || embedded?.version !== expectedVersion.replace(/^[vV]/, "")) {
    errors.push("compatibility metadata version does not match release tag");
  }
  if (external && embedded) {
    const externalComparable = JSON.parse(JSON.stringify(external));
    const embeddedComparable = JSON.parse(JSON.stringify(embedded));
    for (const data of [externalComparable, embeddedComparable]) {
      for (const asset of Object.values(data.platforms ?? {}) as any[]) delete asset.sha256;
    }
    if (canonicalJson(externalComparable) !== canonicalJson(embeddedComparable)) errors.push("external metadata does not match metadata embedded in the verified archive");
  }
  return { valid: errors.length === 0, errors };
}

/**
 * Evaluates whether target release compatibility metadata is compatible with the local installation.
 * Implements explicit legacy fallback policy for releases lacking metadata.
 */
export function checkReleaseCompatibility(
  currentVersion: string,
  currentStateSchemaVersion: number,
  targetMetadata?: ReleaseCompatibilityMetadata | null,
  platformKey: string = "linux-x86_64",
  currentConfigSchemaVersion: number = CURRENT_CONFIG_SCHEMA_VERSION,
  targetVersion?: string
): CompatibilityCheckResult {
  if (!targetMetadata) {
    // Legacy policy: older releases prior to compatibility metadata introduction
    // require an explicit published release identity and their original schema/platform bounds.
    const legacyVersion = targetVersion?.replace(/^[vV]/, "");
    const knownLegacy = legacyVersion === "0.1.0-alpha.1" || legacyVersion === "0.1.0-alpha.2";
    const reasons: string[] = [];
    if (!knownLegacy) reasons.push(`Compatibility metadata is required for target release '${targetVersion ?? "unspecified"}'; only published alpha.1 and alpha.2 have a legacy policy.`);
    if (platformKey !== "linux-x86_64") reasons.push(`Legacy releases do not support platform '${platformKey}'.`);
    if (currentStateSchemaVersion !== 1) reasons.push(`Legacy releases require state schema version 1; current version is ${currentStateSchemaVersion}.`);
    if (currentConfigSchemaVersion !== 1) reasons.push(`Legacy releases require config schema version 1; current version is ${currentConfigSchemaVersion}.`);
    return {
      compatible: reasons.length === 0,
      isLegacy: knownLegacy,
      reasons: reasons.length ? reasons : ["Target release lacks compatibility metadata; proceeding under the explicit published-alpha legacy compatibility policy (schema-1 Linux). Runtime and archive verification remain required."],
    };
  }

  const reasons: string[] = [];
  const validation = validateCompatibilityMetadata(targetMetadata);
  if (!validation.valid) {
    return {
      compatible: false,
      isLegacy: false,
      reasons: [`Malformed compatibility metadata: ${validation.errors.join("; ")}`],
      metadata: targetMetadata,
    };
  }

  if (targetVersion && targetMetadata.version.replace(/^[vV]/, "") !== targetVersion.replace(/^[vV]/, "")) {
    reasons.push(`Compatibility metadata version ${targetMetadata.version} does not match target release ${targetVersion}.`);
  }

  // 1. Platform support check
  const platform = targetMetadata.platforms[platformKey];
  if (!platform) {
    reasons.push(`Target release does not support platform '${platformKey}'. Available: ${Object.keys(targetMetadata.platforms).join(", ")}`);
  }

  // 2. State schema compatibility for downgrade check
  if (targetMetadata.compatibility.stateSchemaVersion < currentStateSchemaVersion) {
    reasons.push(
      `Target version uses state schema version ${targetMetadata.compatibility.stateSchemaVersion}, which cannot read current state schema version ${currentStateSchemaVersion}.`
    );
  }
  if (currentStateSchemaVersion < targetMetadata.compatibility.minSupportedStateVersion) {
    reasons.push(`Target version requires state schema version ${targetMetadata.compatibility.minSupportedStateVersion}, above current version ${currentStateSchemaVersion}.`);
  }
  if (currentConfigSchemaVersion < targetMetadata.compatibility.minSupportedConfigVersion) {
    reasons.push(`Target version requires config schema version ${targetMetadata.compatibility.minSupportedConfigVersion}, above current version ${currentConfigSchemaVersion}.`);
  }
  if (currentConfigSchemaVersion > targetMetadata.compatibility.configSchemaVersion) {
    reasons.push(`Target version uses config schema version ${targetMetadata.compatibility.configSchemaVersion}, which cannot read current config schema version ${currentConfigSchemaVersion}.`);
  }

  // 3. Minimum updater version check
  if (targetMetadata.minimumUpdaterVersion) {
    const minimum = parseSemver(targetMetadata.minimumUpdaterVersion);
    const current = parseSemver(currentVersion);
    if (!current || !minimum || compareSemver(current, minimum) < 0) {
      reasons.push(`Current updater version (${currentVersion}) is below minimum updater version (${targetMetadata.minimumUpdaterVersion}) required by target release.`);
    }
  }

  return {
    compatible: reasons.length === 0,
    isLegacy: false,
    reasons,
    metadata: targetMetadata,
  };
}

