async countRequestTokens(messages: ChatMessage[], tools: ToolDefinition[], requestId: string, signal?: AbortSignal): Promise<RequestCount> {
  if (this.conn.providerId || this.conn.protocol !== "openai-chat") throw new TokenCountError("unsupported", "provider connections have no request-counting endpoint");
  const ep = this.endpoint;
  const denial = this.disclosureDenial(ep, requestId);
  if (denial) throw new TokenCountError("denied", denial.message);
  if (signal?.aborted) throw new TokenCountError("aborted", "cancelled");
  await this.reverifyExpiredKind(signal);
  const kind = LocalLlmClient.serverKindCache.get(this.kindKey(ep));
  // An identity this client had, now unresolved: counting would try the wrong routes and report "unsupported", which
  // the agent latches for good. Say "unavailable" so the next step retries once discovery has recovered.
  if (kind === undefined && this.everDiscovered) throw new TokenCountError("unavailable", "server identity is being re-verified");
  const root = ep.replace(/\/v1\/?$/, "");
  const urls = (kind === "llamacpp" || kind === "vllm") && root !== ep ? [`${ep}/tokenize`, `${root}/tokenize`] : [`${ep}/tokenize`];
  let body: any;
  try {
    await this.prepareCredential(ep, requestId);
    this.preflight(ep, requestId, JSON.stringify(messages).length + JSON.stringify(tools).length);
    body = this.outboundChatBody(ep, requestId, messages, tools);
  } catch (err: any) {
    throw new TokenCountError("denied", boundedProviderText(String(err?.message ?? err)).slice(0, 200));
  }
  let res: Response | undefined;
  let text = "";
  for (let i = 0; i < urls.length; i++) {
    const url = urls[i];
    const reqBody = kind === "llamacpp" && url === `${root}/tokenize`
      ? { content: JSON.stringify({ messages: body.messages, ...(body.tools ? { tools: body.tools } : {}) }), ...body }
      : body;
    try {
      res = await this.fetchResendingStale(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...this.authorization(url), "X-Request-ID": requestId, ...this.routingHeaders(ep) },
        body: JSON.stringify(reqBody),
        signal: metadataSignal(signal),
        ...this.fetchPolicy(),
      });
    } catch (err: any) {
      if (signal?.aborted) throw new TokenCountError("aborted", "cancelled");
      throw new TokenCountError("unavailable", boundedProviderText(String(err?.message ?? err)).slice(0, 160));
    }
    text = await res.text().catch(() => "");
    if ((res.status === 404 || res.status === 405) && i + 1 < urls.length && !/blocked|capacity/i.test(text)) {
      continue;
    }
    break;
  }
  if (!res) throw new TokenCountError("unsupported", "no tokenize endpoint");
  if (res.status === 401 || res.status === 403) throw new TokenCountError("denied", `HTTP ${res.status}`);
  // The gateway answers 404 both for an unknown model and when every worker of the alias is blocked.
  if (res.status === 404) throw new TokenCountError(/blocked|capacity/i.test(text) ? "unavailable" : "unsupported", `HTTP 404 ${boundedProviderText(text).slice(0, 120)}`);
  if (res.status === 405 || res.status === 501) throw new TokenCountError("unsupported", `HTTP ${res.status}`);
  if (!res.ok) throw new TokenCountError("unavailable", `HTTP ${res.status} ${boundedProviderText(text).slice(0, 120)}`);
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw new TokenCountError("malformed", "response is not JSON");
  }
  const count = parseTokenizeResponse(parsed);
  if ("malformed" in count) throw new TokenCountError("malformed", count.malformed);
  return count;
}

/**
 * Side-effect-free reachability check (GET /models) used while waiting out a provider failure. Any answer other
 * than 408/429/5xx shows the server is serving again; the first endpoint that answers becomes active.
 * `preferAlternate` starts with the next endpoint, so a request of unknown status is resubmitted elsewhere
 * when another endpoint is available.
 */
async probeAvailability(signal?: AbortSignal, opts: { timeoutMs?: number; preferAlternate?: boolean } = {}): Promise<ProbeResult> {
  const total = this.endpoints.length;
  const start = opts.preferAlternate && total > 1 ? (this.activeEndpointIndex + 1) % total : this.activeEndpointIndex;
  let last: ProbeResult = { available: false, condition: "TEMPORARILY_UNAVAILABLE" };
  for (let i = 0; i < total; i++) {
    const idx = (start + i) % total;
    last = await this.probeEndpointAt(idx, signal, opts.timeoutMs);
    if (last.available) {
      this.activeEndpointIndex = idx;
      return last;
    }
    // A transport failure that is not a temporary condition ends the walk; an HTTP error moves on to the next endpoint.
    if (last.httpStatus === undefined && !TEMPORARY_CONDITIONS.has(last.condition)) return last;
  }
  return last;
}

/**
 * Probes every endpoint of this connection (the primary and each failover) at once and keeps each result under its own
 * endpoint (endpoints `skip` names are not sent anything and are left out): one endpoint's failure never replaces another's answer. No side effects (the active endpoint stays).
 */
async probeEachEndpoint(signal?: AbortSignal, opts: { timeoutMs?: number; skip?: (endpoint: string) => boolean } = {}): Promise<Array<{ endpoint: string; probe: ProbeResult }>> {
  const all = [...this.endpoints].map((endpoint, idx) => ({ endpoint, idx })).filter(({ endpoint }) => !opts.skip?.(endpoint));
  return Promise.all(all.map(async ({ endpoint, idx }) => ({ endpoint, probe: await this.probeEndpointAt(idx, signal, opts.timeoutMs) })));
}

private async probeEndpointAt(idx: number, signal: AbortSignal | undefined, timeoutMs: number | undefined): Promise<ProbeResult> {
  const timeout = AbortSignal.timeout(timeoutMs ?? 5_000);
  try {
    const res = await this.fetchResendingStale(this.endpointUrl(this.endpoints[idx], "/models"), {
      headers: this.authorization(this.endpoints[idx]),
      signal: signal ? AbortSignal.any([timeout, signal]) : timeout,
      ...this.fetchPolicy(),
    });
    const body = await res.text().catch(() => "");
    if (res.status < 500 && res.status !== 429 && res.status !== 408) {
      return { available: true, condition: "AVAILABLE", httpStatus: res.status };
    }
    const hints = providerHints(res.headers, body);
    return { ...classifyHttpFailure(res.status, hints, body), available: false, httpStatus: res.status, hints, detail: `HTTP ${res.status}` };
  } catch (err: any) {
    if (signal?.aborted) throw err;
    const chain = transportCauseChain(err);
    const { condition } = classifyTransportFailure(chain, "connect", err?.name === "TimeoutError");
    return { available: false, condition, detail: `${err?.message ?? err}${formatCause(chain)}`, ...(err?.name === "TimeoutError" ? { timedOut: true } : {}), codes: chain.flatMap((c) => (c.code ? [c.code] : [])) };
  }
}

async chatCompletion(
  messages: ChatMessage[],
  tools: ToolDefinition[],
  requestId: string = randomUUID(),
  signal?: AbortSignal,
  /** Receipt role override for auxiliary calls (e.g. "compaction"). */
  purpose?: string,
): Promise<ChatMessage> {
  await this.reverifyExpiredKind(signal);
  const response = await this.withReceipt(requestId, purpose, () =>
    this.withOAuthRetry(this.endpoint, requestId, () => this.withParameterRetry(() => this.chatCompletionOnce(messages, tools, requestId, signal))),
  );
  return this.askAgainForNativeCall(response, messages, tools, signal);
}

/**
 * A server that answered a tool request with the call as reply text (never executed, REQ-AGT-112) is asked again, at
 * most twice, and only a native call from an answer is used:
 * 1. with the reply and a note that text is not a call, `tool_choice` unchanged: a model that was only quoting JSON
 *    just answers, one that meant a call makes it natively;
 * 2. only if it wrote the call as text again after that note, with `tool_choice: required`.
 * The retry turns exist only in these requests, never in the returned history. The original reply stands whenever a
 * retry fails (an operator abort still propagates) or yields no native call; a prose answer to the note replaces it.
 * Token usage and cost of every request are summed into the last-usage report.
 */
private async askAgainForNativeCall(response: ChatMessage, messages: ChatMessage[], tools: ToolDefinition[], signal?: AbortSignal, onToken?: StreamTokenCallback): Promise<ChatMessage> {
  if (wireProtocol(this.conn.protocol).native || this.conn.streamOnly || this.askedAgain.has(response) || !isContentCallReply(response, tools, messages)) return response;
  this.askedAgain.add(response);
  const corrected: ChatMessage[] = [...messages, { role: "assistant", content: response.content }, { role: "user", content: CONTENT_CALL_NOTE }];
  const usages = [this.lastUsageReport];
  const ask = async (toolChoice: "auto" | "required"): Promise<ChatMessage | undefined> => {
    const requestId = randomUUID();
    try {
      const answer = await this.withReceipt(requestId, "tool-call-retry", () =>
        this.withOAuthRetry(this.endpoint, requestId, () => this.withParameterRetry(() => this.chatCompletionOnce(corrected, tools, requestId, signal, toolChoice))),
      );
      usages.push(this.lastUsageReport);
      return answer;
    } catch (err) {
      if (signal?.aborted || (err instanceof InferenceError && err.kind === "aborted")) throw err;
      this.emitDiagnostic("error", pc.dim(`[nexus] Asking ${this.conn.label} again for a native tool call failed (${err instanceof Error ? err.message : String(err)}); keeping its first reply.`));
      return undefined;
    }
  };
  const finish = (message: ChatMessage): ChatMessage => {
    this.lastUsageReport = sumUsage(usages);
    return message;
  };
  this.emitDiagnostic("error", pc.dim(`[nexus] ${this.conn.label} answered a tool request with the call as text; telling it so and asking again.`));
  const noted = await ask("auto");
  if (!noted) return finish(response);
  if (noted.tool_calls?.length) return finish({ ...noted, toolCallSource: "feedback" });
  if (!isContentCallReply(noted, tools, messages)) {
    if (typeof noted.content !== "string" || !noted.content.trim()) return finish(response);
    onToken?.(`\n\n${noted.content}`);
    return finish(noted);
  }
  // A model whose listed tool-choice modes exclude `required` would answer a forced request with an error: the
  // corrective note above was the only re-ask it can take. "unknown" (no data) keeps the forced request.
  if (this.conn.providerId && acceptsToolChoice(this.conn.providerId, this.model, "required") === false) {
    this.emitDiagnostic("error", pc.dim(`[nexus] ${this.conn.label} lists no tool_choice=required for ${this.model}; keeping its reply.`));
    return finish(response);
  }
  this.emitDiagnostic("error", pc.dim(`[nexus] ${this.conn.label} wrote the call as text again; asking once more with tool_choice=required.`));
  const forced = await ask("required");
  return finish(forced?.tool_calls?.length ? { ...forced, toolCallSource: "required" } : response);
}

private async chatCompletionOnce(messages: ChatMessage[], tools: ToolDefinition[], requestId: string, signal?: AbortSignal, toolChoice: "auto" | "required" = "auto"): Promise<ChatMessage> {
  if (wireProtocol(this.conn.protocol).native) return this.nativeCompletion(messages, tools, undefined, requestId, signal, this.conn.streamOnly);
  if (this.conn.streamOnly) return this.chatCompletionStreamOnce(messages, tools, undefined, requestId, signal);
  return this.executeWithFailover("chatCompletion", async (currentEp) => {
    if (signal?.aborted) throw abortedError(requestId);
    const url = this.endpointUrl(currentEp, "/chat/completions");
    await this.prepareCredential(currentEp, requestId);
    this.preflight(currentEp, requestId, JSON.stringify(messages).length + JSON.stringify(tools).length);

    // 1. Egress Interception & Quarantine (DISC-001..003, CTX-006, FAIL-003)
    const egressEvaluation = this.boundary.evaluateEgress(
      messages,
      currentEp,
      {
        taskId: this.taskId,
        sessionId: this.sessionId,
        sourceBoundary: "HOST_LOCAL",
      }
    );

    if (!egressEvaluation.allowed) {
      throw egressDenied(
        egressEvaluation.reason || `Egress to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
      );
    }

    const outboundMessages: ChatMessage[] = this.sanitizeHistory(egressEvaluation.sanitizedPayload || messages);

    let outboundTools = tools;
    if (tools.length > 0) {
      const toolsEgress = this.boundary.evaluateEgress(
        tools,
        currentEp,
        {
          taskId: this.taskId,
          sessionId: this.sessionId,
          sourceBoundary: "HOST_LOCAL",
        }
      );
      if (!toolsEgress.allowed) {
        throw egressDenied(
          toolsEgress.reason || `Egress of tools to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
        );
      }
      outboundTools = toolsEgress.sanitizedPayload || tools;
    }
    outboundTools = adaptToolDefinitionsForServer(LocalLlmClient.serverKindCache.get(this.kindKey(currentEp)) ?? "unknown", outboundTools);

    const payload: any = this.chatBody(false, outboundMessages, outboundTools, toolChoice).body;
    this.omitUnsupported(payload);
    this.applyToolGrammar(currentEp, requestId, payload, outboundTools);

    const watchdog = this.createWatchdog(signal, currentEp);
    let res: Response;
    let data: any;
    try {
      res = await this.fetchResendingStale(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...this.authorization(url),
          ...this.providerHeaders(messages),
          "X-Request-ID": requestId,
          ...this.routingHeaders(currentEp),
        },
        body: JSON.stringify(payload),
        signal: watchdog.signal,
        ...this.fetchPolicy(),
      });

      if (res.status === 401 && this.reloadAuthToken(url)) {
        watchdog.done();
        await this.reverifyExpiredKind(signal);
        return this.chatCompletionOnce(messages, tools, requestId, signal, toolChoice);
      }

      if (!res.ok) {
        const errText = await res.text();
        throw this.httpError(res.status, errText, requestId, res.headers);
      }
      data = await res.json();
    } catch (err: any) {
      watchdog.done();
      throw classifyTransportError(err, signal, requestId, "connect");
    } finally {
      watchdog.done();
    }
    const executions = this.pending?.executions;
    this.pending = {
      usage: chatUsage(data.usage),
      providerRequestId: data.id,
      effectiveModel: (data as any).model,
      endpoint: currentEp,
      ...(executions !== undefined ? { executions } : {}),
    };
    if (!data.choices || data.choices.length === 0) {
      throw new InferenceError("protocol_error", "provider", "Model returned empty choices array", { requestId, failoverEligible: false });
    }

    const result = parseChatResponse(data);
    this.refuseChatFinish(result, requestId);
    return result.message;
  });
}

