      }
      toolCalls.push({
        id: tc.id || `call_${Math.random().toString(36).substring(2, 9)}`,
        type: "function",
        function: {
          name,
          arguments: normalized.args,
        },
      });
    }
    if (toolCalls.length > 0 || notices.length > 0) {
      return {
        thoughtText,
        reasoningText,
        toolCalls,
        ...(notices.length > 0 ? { notices } : {}),
      };
    }
  }

  if (!thoughtText && !reasoningText) {
    return {

