  private getContextReserves(): { completion: number; toolResponse: number; total: number } {
    const limits = this.effectiveLimits();
    const completion = limits.outputAllowance;
    const toolResponse = toolHeadroomPolicy(limits.contextLimit, this.config.toolResponseReserveTokens);
    return { completion, toolResponse, total: completion + toolResponse };
  }

  /** The selected model's context and output limits from the models.dev data, for cloud providers only (never the appliance). */
  private referenceLimits(): { context?: number; output?: number } | undefined {
    const provider = this.config.provider;
    if (!provider || !this.config.model) return undefined;
    const model = snapshotModel(provider, this.config.model);
    return model ? { context: model.context, output: model.output } : undefined;
  }

  /**
   * The limits in effect, resolved on every read from the last advertisement and the operator's current settings
   * (resolveLimits): a changed `--context-limit` or allowance takes effect at once, without waiting for a refresh.
   */
  private effectiveLimits(): ReturnType<typeof resolveLimits> {
    const limits = resolveLimits(this.capabilities?.advertised, this.config.contextLimit, this.config.completionReserveTokens, this.referenceLimits());
    if (this.capabilities) Object.assign(this.capabilities, limits);
    return limits;
}

export function snapshotModel(providerId: string, modelId: string): SnapshotModel | undefined {
  const provider = data().byId.get(providerId);
  if (!provider) return undefined;
  let index = modelIndex.get(provider);
  if (!index) {
    index = new Map(provider.models.map((m) => [m.id, m]));
    modelIndex.set(provider, index);
  }
  return index.get(modelId);
}

/** Context window in tokens, or `fallback` (default undefined) when the snapshot has no positive figure. */
export function resolveContext(providerId: string, modelId: string, fallback?: number): number | undefined {
  const context = snapshotModel(providerId, modelId)?.context;
  return context && context > 0 ? context : fallback;
}

/** Reasoning effort levels the model lists, or undefined when the snapshot has none for it (unknown, not "unsupported"). */
export function effortLevels(providerId: string, modelId: string): readonly string[] | undefined {
  const levels = snapshotModel(providerId, modelId)?.effort;
  return levels?.length ? levels : undefined;
}

/**
 * true: the model lists the mode; false: it lists modes and this is not one of them; "unknown": the snapshot has no
 * tool-choice data for it (unknown provider or model, or no `capabilities.tools.choice`), so the caller must not assume.
 */
export function acceptsToolChoice(providerId: string, modelId: string, mode: ToolChoiceMode): boolean | "unknown" {
  const modes = snapshotModel(providerId, modelId)?.toolChoice;
  return modes ? modes.includes(mode) : "unknown";
}

